def f(g, fillmode='bg-1'):
    out=[r[:] for r in g]
    for ri,row in enumerate(g):
        bg=max(set(row),key=row.count)
        fill={'bg-1':bg-1,'fixed':2,'c+1':(max(set(row))+1)%10}[fillmode]
        for c in set(row):
            if c==bg: continue
            i=0
            while i<len(row):
                if row[i]==c:
                    j=i; exp=bg
                    while j+1<len(row) and row[j+1]==exp:
                        j+=1; exp=bg if exp==c else c
                    while j>i and row[j]!=c: j-=1
                    if j-i>=2:
                        for k in range(i+1,j):
                            if row[k]==bg: out[ri][k]=fill
                    i=j+1
                else: i+=1
    return out
